(function(){"use strict";var BG={park:"assets/818b4091_park.webp",school:"assets/611e2c89_school.webp",stream:"assets/4e054b06_stream.webp",alley:"assets/6c9de72d_alley.webp",apart:"assets/785e8aa0_apart.webp",busroad:"assets/a5ec968f_busroad.webp",plaza:"assets/554f6c4a_plaza.webp",overpass:"assets/079011a0_overpass.webp",hill:"assets/83c199ea_hill.webp",sports:"assets/765cbbff_sports.webp"};var STAGE_DEFAULT={212:"busroad",213:"busroad",211:"busroad",210:"hill",1:"school",2:"school",3:"stream",4:"alley",5:"hill"};function battlePos(){try{var o=window.BD&&BD._pendingHazard&&BD._pendingHazard.obj;if(o&&isFinite(o.rx))return{x:(o.rx||0)+(o.rw||0)/2,y:(o.ry||0)+(o.rh||0)/2}}catch(e){}return{x:typeof heroX!=="undefined"?heroX:.5,y:typeof heroY!=="undefined"?heroY:.5}}function isBossBattle(){try{var o=BD._pendingHazard&&BD._pendingHazard.obj;return!!(o&&(o.isBoss||/쌓여있던/.test(o.label||"")))}catch(e){return false}}function nearInfo(sid,p){var st=typeof STAGES!=="undefined"&&STAGES[sid];if(!st)return null;var pool=(st.objects||[]).concat(st.__v24Landmarks||[]);var best=null,bd=.17;pool.forEach(function(o){if(!o)return;var tag=null;var fid=String(o.facilityId||""),lb=String(o.label||"");if(fid||/도서관|문화|캠퍼스|센터|체육|공원|약국|문구|마트|슈퍼|아파트|주택|정류장/.test(lb)){if(/sports|체육/.test(fid+lb))tag="sports";else if(/eco|생태|하천/.test(fid+lb))tag="stream";else if(/park|공원/.test(fid+lb))tag="park";else if(/pharmacy|약국|문구|마트|슈퍼|상가/.test(fid+lb))tag="alley";else if(/아파트|주택|단지/.test(lb))tag="apart";else if(/정류장/.test(lb))tag="busroad";else if(/library|culture|campus|center|도서관|문화|캠퍼스|센터/.test(fid+lb))tag="plaza"}if(!tag)return;var dx=Math.max((o.rx||0)-p.x,0,p.x-((o.rx||0)+(o.rw||0)));var dy=Math.max((o.ry||0)-p.y,0,p.y-((o.ry||0)+(o.rh||0)));var d=Math.hypot(dx,dy);var lim=tag==="apart"?.055:.12;if(d>lim)return;if(d<bd){bd=d;best=tag}});return best}function pickKey(){var sid=Number(typeof currentStage!=="undefined"?currentStage:-1);if(isBossBattle())return"apart";var p=battlePos();var near=nearInfo(sid,p);if(near==="apart"&&sid===210)near="hill";if(near)return near;return STAGE_DEFAULT[sid]||"busroad"}window.BD_pickBattleBg=pickKey;var appliedFor=null;function tick(){try{var active=window.HSR&&HSR.active;var el=document.getElementById("hsr-arena")||document.getElementById("hsr-battle");if(!el)return;if(!active){appliedFor=null;return}if(appliedFor===el.__bdBgKey&&el.__bdBgKey)return;var key=pickKey();var url=BG[key]||BG.busroad;el.style.backgroundImage='linear-gradient(rgba(8,12,20,0.30), rgba(8,12,20,0.52)), url("'+url+'")';el.style.backgroundSize="cover";el.style.backgroundPosition="center center";try{document.body.classList.add("bd-battle-photo-bg")}catch(ePB){}el.__bdBgKey=key;appliedFor=key}catch(e){}}setInterval(tick,300)})();
